insert into public.site_snapshot (id, version, data) values (1, 1, $baseline${"ui":{"openMenu":"Öppna meny","skipLink":"Hoppa till innehållet","closeMenu":"Stäng meny","menuLabel":"Meny","callPrefix":"Ring","closeLabel":"Stäng","cookieText":"Vi vill använda kakor för att se hur besökare använder sidan, så att vi kan göra den bättre. Godkänner du det?","stepPrefix":"Steg","ratingLabel":"{n} av 5 stjärnor","carouselGoTo":"Gå till position {n} av {total}","carouselNext":"Nästa uppdrag","cookieAccept":"Godkänn","cookieDecline":"Nej tack","homeLinkLabel":"Markmontage BEAB AB – startsida","mainMenuLabel":"Huvudmeny","breadcrumbHome":"Hem","cookieSettings":"Kakinställningar","mapTitlePrefix":"Karta:","quickLinksLabel":"Snabblänkar","breadcrumbsLabel":"Brödsmulor","carouselPrevious":"Föregående uppdrag","uppdragFilterLabel":"Filtrera uppdrag"},"form":{"errors":{"name":"Ange ditt namn.","email":"Ange en giltig e-postadress.","phone":"Ange ett giltigt telefonnummer.","contact":"Ange telefonnummer eller e-postadress, så att vi kan nå dig.","workType":"Välj typ av arbete."},"labels":{"name":"Namn","email":"E-post","phone":"Telefon","workType":"Typ av arbete","description":"Kort beskrivning"},"submit":"Skicka förfrågan","sending":"Skickar…","closeHint":"Du kan stänga rutan när som helst genom att klicka utanför eller på","workTypes":{"items":{"annat":{"label":"Annat"},"dranering":{"label":"Dränering"},"va-arbeten":{"label":"VA-arbeten"},"stenlaggning":{"label":"Stenläggning & plattläggning"},"grundlaggning":{"label":"Grundläggning"},"schaktning-markarbeten":{"label":"Schaktning & markarbeten"},"anlaggning-vagar-planer":{"label":"Anläggning av vägar & planer"}},"order":["schaktning-markarbeten","dranering","grundlaggning","va-arbeten","anlaggning-vagar-planer","stenlaggning","annat"]},"sendFailed":"Förfrågan kunde inte skickas. Försök igen eller ring oss på","contactHint":"Det räcker med telefon eller e-post.","confirmation":"Tack! Vi återkommer strax","emailSubject":"Offertförfrågan från {namn}","modalHeading":"Begär offert","closeHintButton":"X","workTypePlaceholder":"Välj typ av arbete","descriptionPlaceholder":"Berätta kort om ditt projekt…"},"pages":{"items":{"hem":{"seo":{"title":"Markarbeten i Västra Götaland | Markmontage BEAB AB","description":"Markmontage BEAB AB utför mark- och grundarbeten i Västra Götaland."},"slug":"","title":"Hem","sections":{"items":{"faq":{"type":"faq","items":{"items":{"tid":{"answer":"Tidsåtgången beror helt på projektets omfattning – allt från en dränering till grundläggning av en hel villa. Vid hembesöket går vi igenom en realistisk tidsplan för just ditt projekt, så att du vet vad du kan förvänta dig innan arbetet startar.","question":"Hur lång tid tar ett mark- eller grundarbete?"},"tjale":{"answer":"Tjäle påverkar när och hur vissa markarbeten kan utföras. Vid hembesöket bedömer vi förutsättningarna för just din tomt och planerar arbetet efter årstid och väderlek, så att du får en realistisk tidsplan redan från start.","question":"Kan ni arbeta året runt, även när det är tjäle i marken?"},"offert":{"answer":"Du kontaktar oss via telefon eller formuläret på sidan och berättar kort om ditt projekt. Därefter bokar vi ett kostnadsfritt hembesök där vi går igenom förutsättningarna tillsammans, och du får en fast offert innan något arbete påbörjas.","question":"Hur går en offertförfrågan till?"},"omraden":{"answer":"Vi utför mark- och grundarbeten i Västra Götaland. Är du osäker på om vi arbetar där du bor är du varmt välkommen att höra av dig, så ger vi dig snabbt besked.","question":"Vilka områden arbetar ni i?"},"fast-pris":{"answer":"Ja, efter det kostnadsfria hembesöket får du en fast offert innan arbetet påbörjas, så att du vet exakt vad som ingår och vad projektet kostar. Skulle nya önskemål tillkomma under projektets gång stämmer vi alltid av med dig innan vi går vidare.","question":"Ger ni fast pris på era projekt?"},"rotavdrag":{"answer":"Som privatperson kan du få rotavdrag på arbetskostnaden för vissa mark- och grundarbeten vid din bostad, till exempel dränering och grundförstärkning i samband med renovering eller tillbyggnad. Avdraget är 30 procent av arbetskostnaden, upp till 50 000 kronor per person och år. Vi drar av beloppet direkt på fakturan och sköter ansökan till Skatteverket.","question":"Kan jag få rotavdrag på mark- och grundarbete?"},"totalentreprenor":{"answer":"Som totalentreprenör tar Markmontage BEAB AB helhetsansvaret för mark- och grundarbetet och samordnar samtliga moment som krävs, från schaktning och dränering till grundläggning och VA. Du behöver bara en kontakt genom hela processen istället för att själv hantera flera olika entreprenörer.","question":"Vad innebär det att ni arbetar som totalentreprenör?"}},"order":["offert","tid","totalentreprenor","tjale","rotavdrag","fast-pris","omraden"]},"label":"","anchor":"faq","hidden":false,"heading":"Vanliga frågor","phonePrompt":"Hittar du inte svaret? Ring oss på"},"hero":{"type":"hero","image":{"src":"/photos/markmontage-bil-solnedgang.webp","variants":[{"width":480,"src":"/photos/markmontage-bil-solnedgang-480.webp"},{"width":800,"src":"/photos/markmontage-bil-solnedgang-800.webp"},{"width":1200,"src":"/photos/markmontage-bil-solnedgang-1200.webp"},{"width":1242,"src":"/photos/markmontage-bil-solnedgang.webp"}],"alt":"Markmontages servicebil med loggan, parkerad i soluppgången","focus":"72% 60%"},"label":"","anchor":"","button":{"href":"#offert","label":"Begär offert"},"hidden":false,"eyebrow":"Markmontage BEAB AB · Sedan 2002","heading":"Mark- och grundarbeten i Västra Götaland","thirdImage":null,"secondImage":null},"grund":{"text":"Därför lägger vi stor vikt vid fackmannamässigt utförande i varje moment – från första spadtaget till färdig yta.","type":"feature","cards":{"items":{"tydligt":{"icon":"Home","link":{"href":"#process","label":"Så går det till"},"text":"Vid ett kostnadsfritt hembesök går vi igenom förutsättningarna på plats. Därefter får du en fast offert, så att du vet vad