ing":5},"therese-jacobsson":{"name":"Therese Jacobsson","image":null,"quote":"","detail":"Recension på Google","rating":5},"ronny-jonsson":{"name":"Ronny Jönsson","image":null,"quote":"","detail":"Recension på Google","rating":5},"tobias-johansson":{"name":"Tobias Johansson","image":null,"quote":"","detail":"Recension på Google","rating":5}}},"label":"","anchor":"kundomdomen","hidden":false,"heading":"Vad våra kunder säger"}},"order":["hero","certifikat","tjanster","uppdrag","siffror","grund","erbjudanden","om-oss","process","kundomdomen","omdomen","kontakt","faq","karta"]}},"om-oss":{"seo":{"title":"Om oss","description":"Markmontage BEAB AB utför mark- och grundarbeten i Västra Götaland sedan 2002."},"slug":"om-oss","title":"Om oss","sections":{"items":{"bild":{"size":"tall","type":"pageHero","image":{"alt":"Markmontages medarbetare samlade vid ett bord utomhus","src":"/photos/markmontage-teamet.webp","focus":"50% 35%","variants":[{"src":"/photos/markmontage-teamet-480.webp","width":480},{"src":"/photos/markmontage-teamet-800.webp","width":800},{"src":"/photos/markmontage-teamet-1200.webp","width":1200},{"src":"/photos/markmontage-teamet-1600.webp","width":1600},{"src":"/photos/markmontage-teamet.webp","width":2000}]},"label":"","anchor":"","hidden":false},"intro":{"type":"aboutIntro","facts":{"items":{"sate":{"label":"Säte","value":"Romelanda, Kungälv"},"org-nr":{"label":"Org.nr","value":"556625-8157"},"grundat":{"label":"Grundat","value":"2002"},"anstallda":{"label":"Anställda","value":"18"},"verksamhet":{"label":"Verksamhet","value":"Mark- och grundarbeten"}},"order":["grundat","anstallda","sate","verksamhet","org-nr"]},"label":"","anchor":"","hidden":false,"heading":"Om oss","factsTitle":"Fakta om oss","paragraphs":["Markmontage BEAB AB är ett entreprenadföretag inom mark- och grundarbeten, verksamt i Västra Götaland. Vi utför bland annat schaktning, dränering, grundläggning, VA-arbeten och fiberinstallation, har egna kranlastbilar för transporter och lyft. Vi tar gärna helhetsansvar som totalentreprenör, med hela markarbetet hos en och samma entreprenör – från schakt och grund till färdig yta.","Markmontage BEAB AB har över 20 års erfarenhet inom branschen. Ett bygge är aldrig starkare än sin grund, och vi lägger därför stor vikt vid fackmannamässigt utförande i varje moment av mark- och grundarbetet.","Markmontage BEAB AB grundades 2002 och har idag 18 anställda.","Du är varmt välkommen att kontakta oss!"],"subheading":"Markmontage BEAB AB har sin bas i Romelanda utanför Kungälv och grundades 2002.","button":null},"jobba":{"tone":"card","type":"text","image":null,"label":"","anchor":"jobba","button":{"href":"#intresseanmalan","label":"Skicka en intresseanmälan"},"hidden":false,"heading":"Jobba hos oss","imageSide":"right","paragraphs":["Vi är ett 18-tal medarbetare som arbetar med mark, kabel och fundament i Västra Götaland. Hos oss jobbar du med maskiner och kranbilar i varierande uppdrag, i ett team där vi hjälps åt.","Är du intresserad av att jobba hos oss? Skicka några rader om dig själv, så hör vi av oss när vi söker folk."]},"grunden":{"link":{"href":"/#tjanster","label":"Se våra tjänster"},"text":"Vi utför bland annat schaktning, dränering, grundläggning, VA-arbeten, fiberinstallation och transporter med kranbil i Västra Götaland – och tar helhetsansvar som totalentreprenör på större projekt. Oavsett uppdrag lägger vi stor vikt vid fackmannamässigt utförande i varje moment.","type":"band","image":null,"label":"","anchor":"","hidden":false,"heading":"Vi lägger grunden för ditt bygge","secondLink":{"href":"#offert","label":"Begär offert"},"secondText":"Du hör av dig, vi kommer ut på ett kostnadsfritt hembesök och du får en fast offert innan något arbete påbörjas. Därefter genomför vi arbetet enligt tidsplan, med löpande avstämning hela vägen.","secondHeading":"Från första spadtaget till färdig yta"},"kontakt":{"text":"","type":"team","label":"","anchor":"kontaktpersoner","hidden":false,"heading":"Kontakta oss dire