"width":480,"src":"/photos/uppdrag-transport12-480.webp"},{"width":800,"src":"/photos/uppdrag-transport12-800.webp"},{"width":1200,"src":"/photos/uppdrag-transport12.webp"}],"alt":"Lyft upp på en mur"},{"src":"/photos/uppdrag-transport13.webp","variants":[{"width":480,"src":"/photos/uppdrag-transport13-480.webp"},{"width":800,"src":"/photos/uppdrag-transport13-800.webp"},{"width":1200,"src":"/photos/uppdrag-transport13.webp"}],"alt":"Lyft av byggmaterial"},{"src":"/photos/uppdrag-transport14.webp","variants":[{"width":480,"src":"/photos/uppdrag-transport14-480.webp"},{"width":800,"src":"/photos/uppdrag-transport14-800.webp"},{"width":1200,"src":"/photos/uppdrag-transport14.webp"}],"alt":"Lyft upp på ett tak"},{"src":"/photos/uppdrag-transport15.webp","variants":[{"width":480,"src":"/photos/uppdrag-transport15-480.webp"},{"width":800,"src":"/photos/uppdrag-transport15-800.webp"},{"width":1200,"src":"/photos/uppdrag-transport15.webp"}],"alt":"Lyft vid en truckshow"},{"src":"/photos/uppdrag-transport16.webp","variants":[{"width":480,"src":"/photos/uppdrag-transport16-480.webp"},{"width":800,"src":"/photos/uppdrag-transport16-800.webp"},{"width":900,"src":"/photos/uppdrag-transport16.webp"}],"alt":"Lyft med grip"},{"src":"/photos/uppdrag-transport17.webp","variants":[{"width":480,"src":"/photos/uppdrag-transport17-480.webp"},{"width":800,"src":"/photos/uppdrag-transport17-800.webp"},{"width":900,"src":"/photos/uppdrag-transport17.webp"}],"alt":"Kranbil i stadsmiljö"},{"src":"/photos/uppdrag-transport18.webp","variants":[{"width":480,"src":"/photos/uppdrag-transport18-480.webp"},{"width":800,"src":"/photos/uppdrag-transport18-800.webp"},{"width":900,"src":"/photos/uppdrag-transport18.webp"}],"alt":"Lyft av växthus"},{"src":"/photos/uppdrag-transport19.webp","variants":[{"width":480,"src":"/photos/uppdrag-transport19-480.webp"},{"width":800,"src":"/photos/uppdrag-transport19-800.webp"},{"width":900,"src":"/photos/uppdrag-transport19.webp"}],"alt":"Kranbil vid belysningsmast"},{"src":"/photos/uppdrag-transport20.webp","variants":[{"width":480,"src":"/photos/uppdrag-transport20-480.webp"},{"width":800,"src":"/photos/uppdrag-transport20-800.webp"},{"width":900,"src":"/photos/uppdrag-transport20.webp"}],"alt":"Lyft av plåtar"},{"src":"/photos/uppdrag-transport07.webp","variants":[{"width":480,"src":"/photos/uppdrag-transport07-480.webp"},{"width":800,"src":"/photos/uppdrag-transport07-800.webp"},{"width":1200,"src":"/photos/uppdrag-transport07.webp"}],"alt":"Kranbilar i arbete på kvällen"},{"alt":"Kranbil lyfter en grävmaskin","src":"/photos/markmontage-kranbil-gravmaskin.webp","variants":[{"src":"/photos/markmontage-kranbil-gravmaskin-480.webp","width":480},{"src":"/photos/markmontage-kranbil-gravmaskin.webp","width":720}]},{"alt":"Kranbil lyfter en byggbod","src":"/photos/markmontage-kranbil-bod.webp","variants":[{"src":"/photos/markmontage-kranbil-bod-480.webp","width":480},{"src":"/photos/markmontage-kranbil-bod-800.webp","width":800},{"src":"/photos/markmontage-kranbil-bod-1200.webp","width":1200},{"src":"/photos/markmontage-kranbil-bod.webp","width":1242}]}]}}},"notFound":{"text":"Sidan du letar efter finns inte längre, eller så har adressen ändrats.","button":{"href":"/","label":"Till startsidan"},"eyebrow":"Fel 404","heading":"Sidan hittades inte","seoTitle":"Sidan hittades inte"},"services":{"items":{"fiber":{"seo":{"title":"Fiberblåsning och fiberinstallation i Västra Götaland","description":"Fiberblåsning och fiberinstallation i Västra Götaland – schakt, rör och inblåsning av fiberkabel."},"icon":"Cable","name":"Fiberblåsning & fiberinstallation","slug":"fiber","image":{"alt":"Servicebil och utrustning för fiberblåsning vid en väg","src":"/photos/tjanst-fiber.webp","variants":[{"src":"/photos/tjanst-fiber-480.webp","width":480},{"src":"/photos/tjanst-fiber-800.webp","width":800},{"src":"/photos/tjanst-fiber-1200.webp","width":1200},{"src":"/photos/tjanst-fiber-1600.webp","width":1600},{"src":"/photos/tjanst-fiber.webp","width":2400}]},"description":["Markmontage BEAB AB utför fiberblåsning och fiberinstallation i Västra Götaland. Vi tar hand om arbetet i marken: schakt, förläggning av rör och kanalisation och inblåsning av fiberkabeln.","Vid fiberblåsning blåses kabeln in i ett tomrör med hjälp av tryckluft. Metoden är skonsam mot kabeln och gör det möjligt att dra långa sträckor i ett stycke.","Vi har också utrustning för att förlägga kabel över vatten, där kabeln läggs ut från pråm med hjälp av båt.","Kontakta oss så berättar vi mer om hur vi kan hjälpa till i ditt fiberprojekt."],"shortDescription":"Fiberblåsning och fiberinstallation – från schakt och rör i marken till inblåst fiberkabel, även över vatten."},"pooler":{"seo":{"title":"Pooler i Västra Götaland","description":"Schakt, grund och montering av glasfiberpooler och betongpooler i Västra Götaland."},"icon":"Waves","name":"Pooler","slug":"pooler","image":{"alt":"Färdig pool med poolskydd och stenläggning runt om","src":"/photos/tjanst-pooler.webp","variants":[{"src":"/photos/tjanst-pooler-480.webp","width":480},{"src":"/photos/tjanst-pooler-800.webp","width":800},{"src":"/photos/tjanst-pooler-1200.webp","width":1200},{"src":"/photos/tjanst-pooler-1600.webp","width":1600},{"src":"/photos/tjanst-pooler.webp","width":2400}]},"description":["Markmontage BEAB AB bygger pooler i Västra Götaland. Vi tar hand om allt arbete i marken, från schakt till färdig pool.","För en glasfiberpool schaktar vi gropen, lägger en bädd av makadam, lyfter poolen på plats med kran och kopplar in rören. För en betongpool lägger vi isolering, gjuter bottenplattan, bygger väggarna av formblock och gjuter dem.","Med egna kranbilar kan vi både frakta poolen och lyfta den på plats, även där det är trångt.","Kontakta oss för ett kostnadsfritt hembesök, så går vi igenom förutsättningarna på din tomt."],"shortDescription":"Schakt, grund och montering av pooler – både glasfiberpooler och gjutna betongpooler."},"dranering":{"seo":{"title":"Dränering i Västra Götaland","description":"Dränering som skyddar grunden mot fukt och sättningsskador, utförd enligt branschens riktlinjer."},"icon":"Droplets","name":"Dränering","slug":"dranering","image":{"alt":"Färdig dränering och återfyllnad längs en villa i tegel","src":"/photos/tjanst-dranering.webp","variants":[{"src":"/photos/tjanst-dranering-480.webp","width":480},{"src":"/photos/tjanst-dranering.webp","width":800}]},"description":["Bristfällig dränering är en av de vanligaste orsakerna till fukt- och sättningsskador i äldre hus. Markmontage BEAB AB utför dränering i Västra Götaland, både vid nybyggnation och som åtgärd vid befintliga fuktproblem.","Arbetet omfattar schaktning runt grunden, ny dränering och fuktskydd, samt återfyllning och iordningställande av marken efteråt. Vi lägger stor vikt vid att dräneringen leder bort vatten på rätt sätt, anpassat efter husets grundläggning och markens lutning.","Dränering vid en befintlig bostad ger i många fall rätt till rotavdrag på arbetskostnaden. Avdraget är 30 procent av arbetskostnaden, högst 50 000 kronor per person och år. Exempel: kostar arbetet 80 000 kronor blir rotavdraget 24 000 kronor, och du betalar 56 000 kronor för arbetet. Material och maskiner ger inget avdrag. Äger ni huset tillsammans kan ni dela på avdraget. Vi drar av beloppet direkt på fakturan och sköter ansökan till Skatteverket.","Kontakta oss för ett kostnadsfritt hembesök, så gör vi en bedömning av dräneringen vid din fastighet."],"shortDescription":"Dränering som skyddar grunden mot fukt och sättningsskador, utförd enligt branschens riktlinjer."},"va-arbeten":{"seo":{"title":"VA-arbeten i Västra Götaland","description":"Vatten- och avloppsarbeten – ledningar på den egna tomten och anslutning till det kommunala nätet."},"icon":"Waves","name":"VA-arbeten","slug":"va-arbeten","image":{"alt":"Grävmaskin och medarbetare i varselkläder vid en schakt","src":"/photos/markmontage-gravmaskin-ror.webp","variants":[{"src":"/photos/markmontage-gravmaskin-ror-480.webp","width":480},{"src":"/photos/markmontage-gravmaskin-ror-800.webp","width":800},{"src":"/photos/markmontage-gravmaskin-ror-1200.webp","width":1200},{"src":"/photos/markmontage-gravmaskin-ror.webp","width":1500}]},"description":["Vatten- och avloppsarbeten kräver både rätt kompetens och rätt tillstånd, eftersom felaktigt utförda VA-installationer kan bli kostsamma att åtgärda. Markmontage BEAB AB utför VA-arbeten i Västra Götaland.","Vi lägger och byter ledningar för vatten, spillvatten och dagvatten, samt utför anslutningar till kommunalt VA-nät eller enskilda avloppsanläggningar. Arbetet utförs enligt gällande branschregler för VA-installationer.","Som totalentreprenör kan vi samordna VA-arbetet med schaktning och återställning av marken, så att du slipper hålla ihop flera separata entreprenörer.","Kontakta oss för en kostnadsfri offert på VA-arbetet vid din fastighet."],"shortDescription":"Vatten- och avloppsarbeten – ledningar på den egna tomten och anslutning till det kommunala nätet."},"stenlaggning":{"seo":{"title":"Stenläggning & plattläggning i Västra Götaland","description":"Stenläggning och plattläggning utomhus med stabilt underlag för gångar, uteplatser och infarter."},"icon":"LayoutGrid","name":"Stenläggning & plattläggning","slug":"stenlaggning","image":{"alt":"Nylagd plattsättning med murblock i en trädgård","src":"/photos/tjanst-stenlaggning.webp","variants":[{"src":"/photos/tjanst-stenlaggning-480.webp","width":480},{"src":"/photos/tjanst-stenlaggning-800.webp","width":800},{"src":"/photos/tjanst-stenlaggning.webp","width":960}]},"description":["En hållbar stenläggning avgörs av underarbetet minst lika mycket som av själva stenen eller plattan. Markmontage BEAB AB utför stenläggning och plattläggning utomhus i Västra Götaland.","Vi bygger upp bärlager och sättsand enligt branschens riktlinjer inför läggning av marksten, plattor eller kantsten till gångar, uteplatser och infarter, så att ytan ligger stabilt och jämnt även efter flera års användning.","Vid behov kombinerar vi stenläggningen med dränering under ytan för att leda bort vatten och minska risken för sättningar och ogräs i fogarna.","Kontakta oss för en kostnadsfri offert på stenläggningen vid din fastighet."],"shortDescription":"Stenläggning och plattläggning utomhus med stabilt underlag för gångar, uteplatser och infarter."},"grundlaggning":{"seo":{"title":"Grundläggning i Västra Götaland","description":"Grundläggning för nybyggnation och tillbyggnad, anpassad efter markens bärighet."},"icon":"Layers","name":"Grundläggning","slug":"grundlaggning","image":{"alt":"Förberedd tomt med makadam inför grundläggning","src":"/photos/tjanst-grundlaggning.webp","variants":[{"src":"/photos/tjanst-grundlaggning-480.webp","width":480},{"src":"/photos/tjanst-grundlaggning-800.webp","width":800},{"src":"/photos/tjanst-grundlaggning-1200.webp","width":1200},{"src":"/photos/tjanst-grundlaggning-1600.webp","width":1600},{"src":"/photos/tjanst-grundlaggning.webp","width":2400}]},"description":["Grunden bär hela byggnaden, och felaktigt utförd grundläggning är svår och kostsam att åtgärda i efterhand. Markmontage BEAB AB utför grundläggning i Västra Götaland, vid såväl nybyggnation som tillbyggnad.","Vi utför bland annat gjutning av platta på mark, grundsulor och källargrunder, alltid anpassat efter markens bärighet och grundvattenförhållandena på platsen. Markisolering och fuktskydd ingår som en naturlig del av arbetet.","Tack vare vår erfarenhet av mark- och grundarbeten vet vi vad som krävs för en grund som håller över tid. Vid behov samordnar vi arbetet med övriga entreprenörer i projektet.","Hör av dig för en kostnadsfri offert, så berättar vi mer om vad som gäller för grundläggningen på just din tomt."],"shortDescription":"Grundläggning för nybyggnation och tillbyggnad, anpassad efter markens bärighet."},"transporter-kranbil":{"seo":{"title":"Transporter och kranbil i Västra Götaland","description":"Transporter och kranlyft med egna kranlastbilar i Västra Götaland."},"icon":"Truck","name":"Transporter & kranbil","slug":"transporter-kranbil","image":{"alt":"Röd kranbil med utfälld kran","src":"/photos/tjanst-transporter-kranbil.webp","variants":[{"src":"/photos/tjanst-transporter-kranbil-480.webp","width":480},{"src":"/photos/tjanst-transporter-kranbil-800.webp","width":800},{"src":"/photos/tjanst-transporter-kranbil-1200.webp","width":1200},{"src":"/photos/tjanst-transporter-kranbil-1600.webp","width":1600},{"src":"/photos/tjanst-transporter-kranbil.webp","width":2400}]},"description":["Markmontage BEAB AB har egna kranlastbilar och utför transporter och kranlyft i Västra Götaland. Med kranen på bilen kan vi både frakta och lyfta på plats.","Vi transporterar bland annat grävmaskiner, betongelement, pooler, växthus och byggmaterial, och lyfter det dit det ska. Med arbetskorg på kranen utför vi också arbeten på höjd, till exempel vid stolpar och ledningar.","Hör av dig med vad som ska fraktas eller lyftas, så återkommer vi med ett förslag."],"shortDescription":"Transporter och lyft med egna kranlastbilar – maskiner, betongelement, material och mycket annat."},"schaktning-markarbeten":{"seo":{"title":"Schaktning & markarbeten i Västra Götaland","description":"Schaktning och markarbeten som förbereder tomten inför bygget, anpassade efter markförhållandena."},"icon":"Shovel","name":"Schaktning & markarbeten","slug":"schaktning-markarbeten","image":{"alt":"Minigrävare och medarbetare som schaktar vid en stenbyggnad","src":"/photos/tjanst-schaktning-markarbeten.webp","variants":[{"src":"/photos/tjanst-schaktning-markarbeten-480.webp","width":480},{"src":"/photos/tjanst-schaktning-markarbeten-800.webp","width":800},{"src":"/photos/tjanst-schaktning-markarbeten-1200.webp","width":1200},{"src":"/photos/tjanst-schaktning-markarbeten-1600.webp","width":1600},{"src":"/photos/tjanst-schaktning-markarbeten.webp","width":1787}]},"description":["Ett bygge börjar alltid under mark, och ett väl förberett underlag avgör hur resten av projektet går. Markmontage BEAB AB utför schaktning och markarbeten i Västra Götaland, både som en del av större entreprenader och som fristående uppdrag.","Vi hanterar schaktning för grund, ledningar och anslutningar, samt terrassering och iordningställande av tomtmark inför fortsatt byggnation. Varje uppdrag anpassas efter markförhållandena på plats, från lera och berg till mer lättarbetad mark.","Som totalentreprenör kan vi samordna schaktningen med efterföljande moment som grundläggning och VA-arbeten, så att projektet flyter på utan onödiga avbrott mellan olika entreprenörer.","Kontakta oss för en kostnadsfri offert, så tittar vi tillsammans på förutsättningarna för just din tomt."],"shortDescription":"Schaktning och markarbeten som förbereder tomten inför bygget, anpassade efter markförhållandena."},"anlaggning-vagar-planer":{"seo":{"title":"Anläggning av vägar & planer i Västra Götaland","description":"Anläggning av vägar, uppfarter och asfalterade eller grusade ytor med hållbar bärighet."},"icon":"Route","name":"Anläggning av vägar & planer","slug":"anlaggning-vagar-planer","image":{"alt":"Avspärrat vägarbete längs en gata","src":"/photos/markmontage-vagarbete-avstangning.webp","variants":[{"src":"/photos/markmontage-vagarbete-avstangning-480.webp","width":480},{"src":"/photos/markmontage-vagarbete-avstangning-800.webp","width":800},{"src":"/photos/markmontage-vagarbete-avstangning-1200.webp","width":1200},{"src":"/photos/markmontage-vagarbete-avstangning.webp","width":1400}]},"description":["En väl anlagd väg eller uppställningsyta kräver rätt uppbyggnad i flera lager för att hålla över tid, oavsett belastning och väderlek. Markmontage BEAB AB utför anläggning av vägar och planer i Västra Götaland.","Vi anlägger uppfarter, parkeringsytor och interna vägar, med förstärkningslager anpassade efter markens bärighet och den tänkta belastningen. Ytorna kan färdigställas med allt från grus till asfalt beroende på behov.","Rätt dränering och lutning i uppbyggnaden är avgörande för att undvika vattenansamling och tjälskador, något vi planerar för redan i markarbetet.","Hör av dig för en kostnadsfri offert, så går vi igenom vad som passar bäst för just din yta."],"shortDescription":"Anläggning av vägar, uppfarter och asfalterade eller grusade ytor med hållbar bärighet."}},"order":["schaktning-markarbeten","dranering","grundlaggning","va-arbeten","fiber","anlaggning-vagar-planer","stenlaggning","pooler","transporter-kranbil"]},"settings":{"logo":{"kind":"wordmark"},"favicon":{"alt":"","src":"/icon.png","variants":[]},"siteUrl":"https://www.markmontagebeab.se","language":"sv","siteName":"Markmontage BEAB AB","analyticsId":"","maintenance":{"text":"Sidan är snart tillbaka. Under tiden når du oss på telefon eller e-post.","enabled":false,"heading":"Vi uppdaterar hemsidan"}},"navigation":{"menu":{"items":{"hem":{"href":"/","kind":"link","label":"Hem"},"jobba":{"href":"/om-oss#jobba","kind":"link","label":"Jobba hos oss"},"om-oss":{"href":"/om-oss","kind":"link","label":"Om oss"},"kontakt":{"href":"/#kontakt","kind":"link","label":"Kontakt"},"omdomen":{"href":"/#omdomen","kind":"link","label":"Omdömen"},"uppdrag":{"href":"/projekt","kind":"link","label":"Uppdrag"},"tjanster":{"href":"/#tjanster","kind":"services","label":"Tjänster"},"hallbarhet":{"href":"/hallbarhet","kind":"link","label":"Hållbarhet"}},"order":["hem","tjanster","uppdrag","om-oss","hallbarhet","omdomen","jobba","kontakt"]},"barLinks":{"items":{"jobba":{"href":"/om-oss#jobba","label":"Jobba hos oss"},"om-oss":{"href":"/om-oss","label":"Om oss"},"kontakt":{"href":"/#kontakt","label":"Kontakt"},"omdomen":{"href":"/#omdomen","label":"Omdömen"},"uppdrag":{"href":"/projekt","label":"Uppdrag"},"tjanster":{"href":"/#tjanster","label":"Tjänster"},"hallbarhet":{"href":"/hallbarhet","label":"Hållbarhet"}},"order":["tjanster","uppdrag","om-oss","hallbarhet","omdomen","jobba","kontakt"]},"menuButton":"Begär offert"},"servicePage":{"cta":{"text":"Kontakta oss för ett kostnadsfritt hembesök